#include "resident/domains/military/military_supply_attrition.hpp"
#include "resident/storage/common_codec.hpp"
#include <iostream>
#include <stdexcept>
using namespace hanmo::resident;
namespace {
int checks=0;void check(bool b,const char* why){++checks;if(!b)throw std::runtime_error(why);}template<class T>T take(Outcome<T> r){if(!r.ok)throw std::runtime_error(r.error.original.code);return std::move(r.value);}
}
int main(){try{
 CommonState seed;seed.identity.tick=3;seed.next_instance_id=4;CommonStore c(seed,std::make_shared<CommonCatalog>());MilitaryState m;MilitaryCatalog cat;GarrisonDefinition camp;camp.id="camp";camp.organization_id="org";camp.food_item_id="grain";camp.ration_per_person=1;MilitaryUnitDefinition unit;unit.id="unit";unit.initial_soldiers=51;camp.units={unit};cat.garrisons={camp};MilitaryAccess access;access.rosters_before=[&](const auto& ids,Integer tick,const StableId& fact){return military_rosters_before(c,m,cat,ids,tick,fact);};
 for(Integer tick=1;tick<=3;++tick){MilitarySupplyFact f;f.id="military:"+std::to_string(tick);f.tick=tick;f.organization_id="org";f.garrison_id="camp";f.item_id="grain";for(Integer i=1;i<=51;++i)f.mouth_ids.push_back("soldier:unit:"+std::to_string(i));f.required=f.shortage=51;c.state().facts.insert(f.id,{f.id,"military_supply","military"});m.supply_facts.push_back(f);}
 MilitarySupplyAttritionPolicy policy;auto first=take(query_military_unit_supply_run(c,m,cat,access,policy,unit.id,"military:1"));check(first.consecutive_shortage_half_days==1&&first.desertion_quota==0,"first actual shortage has no second-period attrition");auto second=take(query_military_unit_supply_run(c,m,cat,access,policy,unit.id,"military:2"));check(second.consecutive_shortage_half_days==2&&second.desertion_quota==2&&second.previous_supply_id=="military:1","second actual shortage quotes ceil51x2percent");auto third=take(query_military_unit_supply_run(c,m,cat,access,policy,unit.id,"military:3"));check(third.consecutive_shortage_half_days==3&&third.shortage_supply_ids.size()==3,"only actual consecutive supplied periods count");
 const auto original=m;m.supply_facts[1].shortage=0;m.supply_facts[1].consumed=51;auto restarted=take(query_military_unit_supply_run(c,m,cat,access,policy,unit.id,"military:3"));check(restarted.consecutive_shortage_half_days==1&&restarted.desertion_quota==0,"real full meal resets shortage streak");m=original;m.supply_facts.erase(m.supply_facts.begin()+1);c.state().facts.erase("military:2");check(!query_military_unit_supply_run(c,m,cat,access,policy,unit.id,"military:3").ok,"missing exact previous period cannot silently reset starvation");m=original;c.state().facts.insert("military:2",{"military:2","military_supply","military"});check(!query_military_unit_supply_run(c,m,cat,access,policy,unit.id,"military:3").ok,"reordered Common supply source rejected");
 c.state().facts={};for(const auto& f:m.supply_facts)c.state().facts.insert(f.id,{f.id,"military_supply","military"});auto before=take(render_boundary_json(encode_common_state(c.state())));take(query_military_unit_supply_run(c,m,cat,access,policy,unit.id,"military:3"));check(before==take(render_boundary_json(encode_common_state(c.state()))),"pure read does not spend food or change Common");m.supply_facts[2].mouth_ids.pop_back();check(!query_military_unit_supply_run(c,m,cat,access,policy,unit.id,"military:3").ok,"missing actual wounded or fit mouth rejected");
 std::cout<<"MILITARY_SUPPLY_ATTRITION_SOURCE="<<checks<<" FAILURES=0 SCOPE=PURE_READ_SOURCE_ONLY\n";return 0;
 }catch(const std::exception& e){std::cerr<<"MILITARY_SUPPLY_ATTRITION_SOURCE_FAIL "<<checks<<" "<<e.what()<<'\n';return 1;}}
